INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(31611, 'Luke 22:21', 'Luke', 22, 21, 'خو ګورئ، هغه څوک چې زما سره به خیانت کوي هغه دلته زما سره په دسترخوان ناست دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_21.mp3', '', 1761754199, 1761754199),
(31612, 'Luke 22:22', 'Luke', 22, 22, 'لکه څنګه چې د خدای له خوا مقرره وه چې د انسان زوی باید مړ شي، خو افسوس د هغه چا په حال چې د هغه سره خیانت کوي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_22.mp3', '', 1761754199, 1761754199),
(31613, 'Luke 22:23', 'Luke', 22, 23, 'بیا هغوی په خپلو کې یو د بل څخه پوښتنې پیل کړې چې په دوی کې به څوک دا کار کوي. د لویۍ په هکله بحث', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_23.mp3', '', 1761754199, 1761754199),
(31614, 'Luke 22:24', 'Luke', 22, 24, 'بیا د هغوی ترمنځ ناندرۍ پیل شوې چې په دوی کې به څوک د ټولو څخه لوی وګڼل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_24.mp3', '', 1761754199, 1761754199),
(31615, 'Luke 22:25', 'Luke', 22, 25, 'عیسی هغوی ته وویل: «د غیریهودیانو پاچاهان په خپلو خلکو باداري کوي او واکمنان د خلکو خیرخواه ګڼل کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_25.mp3', '', 1761754199, 1761754199),
(31616, 'Luke 22:26', 'Luke', 22, 26, 'خو تاسو داسې مه اوسئ، بلکې په تاسو کې دې تر ټولو لوی خپل ځان کوچنی وګڼي او مشر دې د خدمتګار په شان وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_26.mp3', '', 1761754199, 1761754199),
(31617, 'Luke 22:27', 'Luke', 22, 27, 'خلک څه فکر کوي چې په دوی دواړو کې کوم یو لوی دی، هغه څوک چې ډوډۍ ته ناست دی او یا هغه څوک چې خدمت کوي؟ په یقین سره هغه څوک چې ډوډۍ ته ناست دی. خو زه ستاسو په منځ کې د یو خدمتګار په شان یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_27.mp3', '', 1761754199, 1761754199),
(31618, 'Luke 22:28', 'Luke', 22, 28, 'خو تاسو زما د ازمېښتونو په وخت کې زما سره ولاړ وئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_28.mp3', '', 1761754199, 1761754199),
(31619, 'Luke 22:29', 'Luke', 22, 29, 'لکه څنګه چې زما پلار ماته د پاچاهۍ حق راکړی دی، زه هم تاسو ته دا حق درکوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_29.mp3', '', 1761754199, 1761754199),
(31620, 'Luke 22:30', 'Luke', 22, 30, 'تاسو به زما په پاچاهۍ کې زما په دسترخوان خورئ او څښئ او په تختونو باندې به کښېنئ او د اسراییلو په دولسو قبیلو باندې به حکومت کوئ.» د پطروس د انکار په هکله د عیسی پېشګويي (متي ۲۶‏:‌۳۱‌‏-‌۳۵ او مرقوس ۱۴‏:‌۲۷‌‏-‌۳۱ او یوحنا ۱۳‏:‌۳۶‌‏-‌۳۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_30.mp3', '', 1761754199, 1761754199),
(31621, 'Luke 22:31', 'Luke', 22, 31, 'عیسی وویل: «ای شمعونه، ای شمعونه! واوره، شیطان وغوښتل چې تاسو ټول وازمایي، ښه او بد سره بېل کړي لکه څنګه چې بزګر د غنمو څخه بوس بېل کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_31.mp3', '', 1761754199, 1761754199),
(31622, 'Luke 22:32', 'Luke', 22, 32, 'خو شمعونه! ما ستا دپاره دعا کړې ده چې ایمان دې له منځه لاړ نه شي. کله چې دې توبه وویستله او بېرته ماته راوګرځېدلې، نو خپل ورونه دې قوي کړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_32.mp3', '', 1761754199, 1761754199),
(31623, 'Luke 22:33', 'Luke', 22, 33, 'پطروس ځواب ورکړ: «ای استاذه! زه ستا سره زندان او مرګ ته هم تیار یم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_33.mp3', '', 1761754199, 1761754199),
(31624, 'Luke 22:34', 'Luke', 22, 34, 'عیسی وویل: «ای پطروسه! زه تاته وایم چې نن شپه به د چرګ د اذان څخه مخکې درې ځلې ووایې چې ته ما نه پېژنې.» د پیسو کڅوړه، خورجین او توره', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_34.mp3', '', 1761754199, 1761754199),
(31625, 'Luke 22:35', 'Luke', 22, 35, 'عیسی د هغوی څخه پوښتنه وکړه: «کله چې ما تاسو بې د پیسو له کڅوړې، بې‌خورجینې او بې له څپلیو ولېږلئ، ایا په هغه وخت کې ستاسو سره د کوم شي کمی ؤ؟» هغوی ځواب ورکړ: «نه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_35.mp3', '', 1761754199, 1761754199),
(31626, 'Luke 22:36', 'Luke', 22, 36, 'عیسی وویل: «خو اوس هرڅوک چې د پیسو کڅوړه لري هغه دې د ځان سره واخلي او همدارنګه خپل خورجین هم. او د هرچا سره چې توره نه وي، نو خپله چپنه دې خرڅه کړي او یوه توره دې واخلي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_36.mp3', '', 1761754199, 1761754199),
(31627, 'Luke 22:37', 'Luke', 22, 37, 'ځکه زه تاسو ته وایم چې د خدای د کلام دا لیکنه باید پوره شي چې وایي: هغه به په مجرمانو کې وشمېرل شي. ځکه هرڅه چې زما په هکله لیکل شوي دي هغه به رښتیا شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_37.mp3', '', 1761754199, 1761754199),
(31628, 'Luke 22:38', 'Luke', 22, 38, 'شاګردانو وویل: «ګوره استاذه! زمونږ سره دلته دوه تورې دي.» عیسی ځواب ورکړ: «دا بس دي.» عیسی د زیتون په غره کې دعا کوي (متي ۲۶‏:‌۳۶‌‏-‌۴۶ او مرقوس ۱۴‏:‌۳۲‌‏-‌۴۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_38.mp3', '', 1761754199, 1761754199),
(31629, 'Luke 22:39', 'Luke', 22, 39, 'عیسی دباندې ووت او د خپل عادت له مخې د زیتون غره ته روان شو او شاګردان یې هم ورپسې لاړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_39.mp3', '', 1761754199, 1761754199),
(31630, 'Luke 22:40', 'Luke', 22, 40, 'کله چې هغه ځای ته ورسېده، نو هغوی ته یې وویل: «دعا وکړئ چې په ازمېښت کې ونه لوېږئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_40.mp3', '', 1761754199, 1761754199),
(31631, 'Luke 22:41', 'Luke', 22, 41, 'بیا عیسی د هغوی څخه یو څو ګامه لېرې لاړ، په ګونډو شو او دعا یې وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_41.mp3', '', 1761754199, 1761754199),
(31632, 'Luke 22:42', 'Luke', 22, 42, 'هغه وویل: «ای پلاره! که چېرې ستا رضا وي، نو دا پیاله زما څخه لېرې کړه. خو زما رضا نه، بلکې ستا رضا دې پوره شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_42.mp3', '', 1761754199, 1761754199),
(31633, 'Luke 22:43', 'Luke', 22, 43, 'بیا د اسمان څخه یوه فرښته هغه ته راښکاره شوه او هغه ته یې قوت ورکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_43.mp3', '', 1761754199, 1761754199),
(31634, 'Luke 22:44', 'Luke', 22, 44, 'عیسی په ډېر سخت حالت کې ؤ او په ډېر جوش سره یې دعا وکړه او خولې یې د وینو د څاڅکو په شان په ځمکه باندې څڅېدلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_44.mp3', '', 1761754199, 1761754199),
(31635, 'Luke 22:45', 'Luke', 22, 45, 'کله چې عیسی د دعا څخه راپاڅېده، نو شاګردانو ته راغی او ویې لیدل چې هغوی له غمه ستومانه او ویده شوي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_45.mp3', '', 1761754199, 1761754199),
(31636, 'Luke 22:46', 'Luke', 22, 46, 'هغوی ته یې وویل: «تاسو ولې ویده یئ؟ پاڅېږئ او دعا وکړئ چې په ازمېښت کې ونه لوېږئ.» د عیسی سره خیانت کول او نیول (متي ۲۶‏:‌۴۷‌‏-‌۵۶ او مرقوس ۱۴‏:‌۴۳‌‏-‌۵۰ او یوحنا ۱۸‏:‌۳‌‏-‌۱۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_46.mp3', '', 1761754199, 1761754199),
(31637, 'Luke 22:47', 'Luke', 22, 47, 'عیسی لا خبرې کولې چې یوه ډله راغله او یهودا چې د هغو دولسو شاګردانو څخه ؤ، د هغوی څخه مخکې روان ؤ. هغه عیسی ته ورنژدې شو چې ښکل یې کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_47.mp3', '', 1761754199, 1761754199),
(31638, 'Luke 22:48', 'Luke', 22, 48, 'خو عیسی وویل: «ای یهودا! ایا په ښکلولو سره د انسان زوی دښمنانو ته په لاس ورکوې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_48.mp3', '', 1761754199, 1761754199),
(31639, 'Luke 22:49', 'Luke', 22, 49, 'کله چې د عیسی شاګردانو ولیدل چې څه کیږي، نو ویې ویل: «استاذه! ایا په تورو یې ووهو؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_49.mp3', '', 1761754199, 1761754199),
(31640, 'Luke 22:50', 'Luke', 22, 50, 'د هغوی څخه یو تن د لوی کاهن په نوکر ګوزار وکړ او د هغه ښي غوږ یې پرې کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_50.mp3', '', 1761754199, 1761754199),
(31641, 'Luke 22:51', 'Luke', 22, 51, 'خو عیسی وویل: «بس یې دی.» عیسی د هغه سړي په غوږ باندې خپل لاس کېښود او هغه یې روغ کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_51.mp3', '', 1761754199, 1761754199),
(31642, 'Luke 22:52', 'Luke', 22, 52, 'بیا عیسی مشرانو کاهنانو، د خدای د کور د ساتونکو آمرانو او نورو قومي مشرانو ته چې د هغه د نیولو دپاره راغلي وو، وویل: «ایا زه کوم داړه مار یم چې د تورو او کوتکونو سره زما د نیولو دپاره راغلي یئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_52.mp3', '', 1761754199, 1761754199),
(31643, 'Luke 22:53', 'Luke', 22, 53, 'زه هره ورځ ستاسو سره د خدای په کور کې وم او تاسو زما د نیولو هڅه ونه کړه. خو دا وخت چې تیاره خپره ده، نو ستاسو وخت دی.» پطروس له عیسی څخه انکار کوي (متي ۲۶‏:‌۵۷‌‏-‌۵۸،‌۶۹‌‏-‌۷۵ او مرقوس ۱۴‏:‌۵۳‌‏-‌۵۴،‌۶۶‌‏-‌۷۲ او یوحنا ۱۸‏:‌۱۲‌‏-‌۱۸،‌۲۵‌‏-‌۲۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_53.mp3', '', 1761754199, 1761754199),
(31644, 'Luke 22:54', 'Luke', 22, 54, 'هغوی عیسی ونیوه او د لوی کاهن کور ته یې بوته او پطروس د لېرې نه ورپسې روان ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_54.mp3', '', 1761754199, 1761754199),
(31645, 'Luke 22:55', 'Luke', 22, 55, 'هغوی د حوېلۍ په منځ کې اور بل کړ او ګردچاپېره ورڅخه کښېناستل او پطروس هم د هغوی سره کښېناست.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_55.mp3', '', 1761754199, 1761754199),
(31646, 'Luke 22:56', 'Luke', 22, 56, 'په داسې حال کې چې هغه د اور رڼا ته ناست ؤ یوې وینځې هغه ولیده، نو په ځیر یې ورته وکتل او ویې ویل: «دا سړی هم د عیسی سره ؤ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_56.mp3', '', 1761754199, 1761754199),
(31647, 'Luke 22:57', 'Luke', 22, 57, 'خو پطروس منکر شو او ویې ویل: «ای ښځې! زه هغه نه پېژنم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_57.mp3', '', 1761754199, 1761754199),
(31648, 'Luke 22:58', 'Luke', 22, 58, 'لږ وروسته یو بل سړي هم هغه ته وکتل او ویې ویل: «ته هم د هغو له ډلې څخه یې.» خو پطروس وویل: «ای وروره! زه نه یم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_58.mp3', '', 1761754199, 1761754199),
(31649, 'Luke 22:59', 'Luke', 22, 59, 'شاوخوا یو ساعت وروسته یو بل سړي تایید کړه او ویې ویل: «په دې کې هېڅ شک نشته چې دا سړی هم د عیسی سره ؤ، ځکه چې هغه هم جلیلي دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_59.mp3', '', 1761754199, 1761754199),
(31650, 'Luke 22:60', 'Luke', 22, 60, 'خو پطروس ځواب ورکړ: «ای وروره! زه نه پوهېږم چې ته څه وایې.» هغه لا خبرې کولې چې سمدلاسه چرګ اذان وکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_60.mp3', '', 1761754199, 1761754199),
(31651, 'Luke 22:61', 'Luke', 22, 61, 'عیسی مخ راواړاوه او پطروس ته یې وکتل او پطروس ته د عیسی خبرې ور په یاد شوې چې هغه ته یې ویلي وو: «نن شپه به د چرګ د اذان څخه مخکې درې ځلې ووایې چې ته ما نه پېژنې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_61.mp3', '', 1761754199, 1761754199),
(31652, 'Luke 22:62', 'Luke', 22, 62, 'پطروس دباندې ووت او په چیغو چیغو یې وژړل. د عیسی سپکاوی او وهل (متي ۲۶‏:‌۶۷‌‏-‌۶۸ او مرقوس ۱۴‏:‌۶۵)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_62.mp3', '', 1761754199, 1761754199),
(31653, 'Luke 22:63', 'Luke', 22, 63, 'کومو خلکو چې د عیسی ساتنه کوله په هغه باندې ملنډې ووهلې او ویې واهه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_63.mp3', '', 1761754199, 1761754199),
(31654, 'Luke 22:64', 'Luke', 22, 64, 'د هغه سترګې یې وتړلې او پوښتنه یې ترې وکړه: «اوس له غیبو ووایه چې ته چا ووهلې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_64.mp3', '', 1761754199, 1761754199),
(31655, 'Luke 22:65', 'Luke', 22, 65, 'او نورې ډېرې سپکې خبرې یې هم ورته وکړې. عیسی د مذهبي شورا په مخکې (متي ۲۶‏:‌۵۹‌‏-‌۶۶ او مرقوس ۱۴‏:‌۵۵‌‏-‌۶۴ او یوحنا ۱۸‏:‌۱۹‌‏-‌۲۴)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_65.mp3', '', 1761754199, 1761754199),
(31656, 'Luke 22:66', 'Luke', 22, 66, 'کله چې ورځ شوه نو قومي مشران، د کاهنانو مشران او د شریعت عالمان سره راټول شول او عیسی یې خپلې شورا ته راوست.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_66.mp3', '', 1761754199, 1761754199),
(31657, 'Luke 22:67', 'Luke', 22, 67, 'هغوی وویل: «مونږ ته ووایه چې ته مسیح یې؟» هغه ځواب ورکړ: «که زه تاسو ته ووایم، نو په ما به باور ونه کړئ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_67.mp3', '', 1761754199, 1761754199),
(31658, 'Luke 22:68', 'Luke', 22, 68, 'او که زه درڅخه پوښتنه وکړم، نو تاسو به ځواب رانه کړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke22_verse_68.mp3', '', 1761754199, 1761754199),
